t6_gpio_pp50:
/* PC13 — 通用推挽输出 50MHz */
RCC->APB2ENR |= RCC_APB2ENR_IOPCEN;
__DSB();
GPIOC->CRH &= ~(0xFUL << 20);
GPIOC->CRH |=  (0x3UL << 20);

t6_i2c1_std:
/* ========================================================================
 * I2C1 — 100kHz standard mode, SCL=PB6 SDA=PB7
 * CCR=0x0B4 (180), TRISE=0x25 (37)
 * WARNING: STM32F103 I2C has known errata. Consider software I2C for
 *          production use. See f103_known_issues.json.
 * ======================================================================== */

/* 1. Clock enable */
RCC->APB1ENR |= RCC_APB1ENR_I2C1EN;
RCC->APB2ENR |= RCC_APB2ENR_IOPBEN | RCC_APB2ENR_IOPBEN;
__DSB();

/* 2. GPIO — SCL=PB6 AF-OD, SDA=PB7 AF-OD */
GPIOB->CRL &= ~(0xFUL << 24);
GPIOB->CRL |=  (0xFUL << 24);
GPIOB->CRL &= ~(0xFUL << 28);
GPIOB->CRL |=  (0xFUL << 28);

/* 3. I2C1 config */
I2C1->CR2 = 36;               // FREQ = PCLK1 MHz
I2C1->CCR = 0x0B4;       // 100kHz, CCR=180
I2C1->TRISE = 37;                // max rise time = 37
I2C1->CR1 = 1;                  // PE=1, enable

/* 4. Poll write helper — returns 0 = OK, negative = timeout code
 *   (self-contained: no external error-chain dependency) */
#include <stdint.h>
static int i2c1_write(uint8_t dev_addr, uint8_t reg, uint8_t data) {
    uint32_t timeout = 100000;
    while (I2C1->SR2 & (1<<1)) {        // wait BUSY=0
        if (--timeout == 0) return -1;   // I2C BUSY timeout
    }
    I2C1->CR1 |= (1<<8);                 // START
    timeout = 100000;
    while (!(I2C1->SR1 & 1)) {           // wait SB
        if (--timeout == 0) return -2;   // I2C START timeout
    }
    I2C1->DR = (dev_addr << 1);          // ADDR + W
    timeout = 100000;
    while (!(I2C1->SR1 & (1<<1))) {       // wait ADDR
        if (--timeout == 0) return -3;   // I2C ADDR timeout
    }
    (void)I2C1->SR2;                       // clear ADDR
    I2C1->DR = reg;                       // send register
    timeout = 100000;
    while (!(I2C1->SR1 & (1<<7))) {       // wait TXE
        if (--timeout == 0) return -4;   // I2C TXE timeout
    }
    I2C1->DR = data;                      // send data
    timeout = 100000;
    while (!(I2C1->SR1 & (1<<7))) {
        if (--timeout == 0) return -4;   // I2C TXE timeout
    }
    timeout = 100000;
    while (!(I2C1->SR1 & (1<<2))) {       // wait BTF
        if (--timeout == 0) return -5;   // I2C BTF timeout
    }
    I2C1->CR1 |= (1<<9);                  // STOP
    return 0;
}
